const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageNumber, PageBreak, VerticalAlign
} = require('docx');
const fs = require('fs');

const BRAND_DARK = "1A1A2E";
const BRAND_ACCENT = "C9A96E";
const LIGHT_GOLD = "F5EDD8";
const LIGHT_GRAY = "F7F7F7";
const MID_GRAY = "E8E8E8";
const WHITE = "FFFFFF";
const TEXT_DARK = "1A1A2E";
const TEXT_BODY = "333333";

const border = { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorders = {
  top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
};

function spacer(pt = 120) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: pt, after: 0 } });
}

function rule(color = BRAND_ACCENT) {
  return new Paragraph({
    children: [new TextRun("")],
    border: { bottom: { style: BorderStyle.SINGLE, size: 12, color, space: 1 } },
    spacing: { before: 0, after: 0 },
  });
}

function sectionHeader(label) {
  return new Paragraph({
    children: [
      new TextRun({ text: label, bold: true, size: 28, color: WHITE, font: "Arial" })
    ],
    shading: { fill: BRAND_DARK, type: ShadingType.CLEAR },
    spacing: { before: 240, after: 0 },
    indent: { left: 160, right: 160 },
  });
}

function formulaBox(formula) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: {
              top: { style: BorderStyle.SINGLE, size: 8, color: BRAND_ACCENT },
              bottom: { style: BorderStyle.SINGLE, size: 8, color: BRAND_ACCENT },
              left: { style: BorderStyle.SINGLE, size: 8, color: BRAND_ACCENT },
              right: { style: BorderStyle.SINGLE, size: 8, color: BRAND_ACCENT },
            },
            shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
            margins: { top: 140, bottom: 140, left: 240, right: 240 },
            width: { size: 9360, type: WidthType.DXA },
            children: [
              new Paragraph({
                alignment: AlignmentType.CENTER,
                children: [
                  new TextRun({ text: formula, bold: true, size: 22, font: "Courier New", color: BRAND_DARK })
                ]
              })
            ]
          })
        ]
      })
    ]
  });
}

function kpiBlock(number, title, formula, explanation, yourNumbers, benchmark) {
  const rows = [];

  // Header row
  rows.push(new TableRow({
    children: [
      new TableCell({
        columnSpan: 2,
        borders: noBorders,
        shading: { fill: BRAND_DARK, type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 200, right: 200 },
        width: { size: 9360, type: WidthType.DXA },
        children: [
          new Paragraph({
            children: [
              new TextRun({ text: `${number}  |  `, bold: true, size: 24, color: BRAND_ACCENT, font: "Arial" }),
              new TextRun({ text: title, bold: true, size: 24, color: WHITE, font: "Arial" }),
            ]
          })
        ]
      })
    ]
  }));

  // Formula row
  rows.push(new TableRow({
    children: [
      new TableCell({
        columnSpan: 2,
        borders: {
          top: { style: BorderStyle.NONE, size: 0, color: WHITE },
          bottom: { style: BorderStyle.NONE, size: 0, color: WHITE },
          left: { style: BorderStyle.SINGLE, size: 2, color: MID_GRAY },
          right: { style: BorderStyle.SINGLE, size: 2, color: MID_GRAY },
        },
        shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 200, right: 200 },
        width: { size: 9360, type: WidthType.DXA },
        children: [
          new Paragraph({
            alignment: AlignmentType.CENTER,
            children: [
              new TextRun({ text: "FORMULA:  ", bold: true, size: 18, color: TEXT_DARK, font: "Arial" }),
              new TextRun({ text: formula, bold: true, size: 18, font: "Courier New", color: BRAND_DARK })
            ]
          })
        ]
      })
    ]
  }));

  // Body row: explanation + your numbers
  rows.push(new TableRow({
    children: [
      new TableCell({
        borders: {
          top: { style: BorderStyle.NONE, size: 0, color: WHITE },
          bottom: { style: BorderStyle.SINGLE, size: 2, color: MID_GRAY },
          left: { style: BorderStyle.SINGLE, size: 2, color: MID_GRAY },
          right: { style: BorderStyle.SINGLE, size: 1, color: MID_GRAY },
        },
        shading: { fill: WHITE, type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 180, right: 180 },
        width: { size: 6240, type: WidthType.DXA },
        children: [
          new Paragraph({
            children: [new TextRun({ text: "WHAT IT MEANS", bold: true, size: 18, color: BRAND_ACCENT, font: "Arial" })],
            spacing: { after: 60 }
          }),
          new Paragraph({
            children: [new TextRun({ text: explanation, size: 18, color: TEXT_BODY, font: "Arial" })],
            spacing: { after: 0 }
          })
        ]
      }),
      new TableCell({
        borders: {
          top: { style: BorderStyle.NONE, size: 0, color: WHITE },
          bottom: { style: BorderStyle.SINGLE, size: 2, color: MID_GRAY },
          left: { style: BorderStyle.SINGLE, size: 1, color: MID_GRAY },
          right: { style: BorderStyle.SINGLE, size: 2, color: MID_GRAY },
        },
        shading: { fill: LIGHT_GRAY, type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 180, right: 180 },
        width: { size: 3120, type: WidthType.DXA },
        children: [
          new Paragraph({
            children: [new TextRun({ text: "YOUR NUMBERS", bold: true, size: 18, color: BRAND_ACCENT, font: "Arial" })],
            spacing: { after: 60 }
          }),
          ...yourNumbers.map(line => new Paragraph({
            children: [new TextRun({ text: line, size: 18, color: TEXT_BODY, font: "Arial" })],
            spacing: { after: 40 }
          })),
          ...(benchmark ? [
            spacer(80),
            new Paragraph({
              children: [new TextRun({ text: "BENCHMARK", bold: true, size: 16, color: TEXT_DARK, font: "Arial" })],
              spacing: { after: 40 }
            }),
            new Paragraph({
              children: [new TextRun({ text: benchmark, size: 16, color: TEXT_BODY, font: "Arial" })],
            })
          ] : [])
        ]
      })
    ]
  }));

  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [6240, 3120],
    rows
  });
}

const doc = new Document({
  styles: {
    default: {
      document: { run: { font: "Arial", size: 22, color: TEXT_BODY } }
    },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 36, bold: true, font: "Arial", color: BRAND_DARK },
        paragraph: { spacing: { before: 320, after: 160 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 26, bold: true, font: "Arial", color: BRAND_DARK },
        paragraph: { spacing: { before: 240, after: 120 }, outlineLevel: 1 }
      }
    ]
  },
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 640, hanging: 320 } }, run: { color: BRAND_ACCENT } }
        }]
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1080, bottom: 1080, left: 1080 }
      }
    },
    children: [

      // COVER BLOCK
      new Table({
        width: { size: 10080, type: WidthType.DXA },
        columnWidths: [10080],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders: noBorders,
                shading: { fill: BRAND_DARK, type: ShadingType.CLEAR },
                margins: { top: 480, bottom: 480, left: 480, right: 480 },
                width: { size: 10080, type: WidthType.DXA },
                children: [
                  new Paragraph({
                    alignment: AlignmentType.CENTER,
                    children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 20, color: BRAND_ACCENT, font: "Arial" })],
                    spacing: { after: 80 }
                  }),
                  new Paragraph({
                    alignment: AlignmentType.CENTER,
                    children: [new TextRun({ text: "Know Your Numbers", bold: true, size: 52, color: WHITE, font: "Arial" })],
                    spacing: { after: 100 }
                  }),
                  new Paragraph({
                    alignment: AlignmentType.CENTER,
                    children: [new TextRun({ text: "The Med Spa Owner's KPI Reference Guide", size: 26, color: LIGHT_GOLD, font: "Arial" })],
                    spacing: { after: 160 }
                  }),
                  new Paragraph({
                    alignment: AlignmentType.CENTER,
                    children: [new TextRun({ text: "theluxoracollective.co", size: 18, color: BRAND_ACCENT, font: "Arial" })],
                  }),
                ]
              })
            ]
          })
        ]
      }),

      spacer(240),

      // Intro
      new Paragraph({
        children: [new TextRun({
          text: "This guide gives you the 10 numbers every profitable med spa tracks, plus the formula to calculate your Lifetime Value per client. Fill in your own numbers as you go. These metrics are your dashboard. Once you know them, you stop guessing and start making decisions.",
          size: 22, color: TEXT_BODY, font: "Arial"
        })],
        spacing: { after: 60 }
      }),

      spacer(40),
      rule(),
      spacer(200),

      // LTV SPOTLIGHT - first, most important
      new Paragraph({
        children: [new TextRun({ text: "START HERE: Lifetime Value Per Client (LTV)", bold: true, size: 32, color: BRAND_DARK, font: "Arial" })],
        spacing: { after: 120 }
      }),

      new Paragraph({
        children: [new TextRun({
          text: "LTV is the single most important number in your business. It tells you exactly how much one client is worth to you over the full course of your relationship. Without it, every marketing and pricing decision is a guess.",
          size: 22, color: TEXT_BODY, font: "Arial"
        })],
        spacing: { after: 160 }
      }),

      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [9360],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders: {
                  top: { style: BorderStyle.SINGLE, size: 12, color: BRAND_ACCENT },
                  bottom: { style: BorderStyle.SINGLE, size: 12, color: BRAND_ACCENT },
                  left: { style: BorderStyle.SINGLE, size: 12, color: BRAND_ACCENT },
                  right: { style: BorderStyle.SINGLE, size: 12, color: BRAND_ACCENT },
                },
                shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
                margins: { top: 180, bottom: 180, left: 300, right: 300 },
                width: { size: 9360, type: WidthType.DXA },
                children: [
                  new Paragraph({
                    alignment: AlignmentType.CENTER,
                    children: [new TextRun({ text: "LTV  =  Average Visit Value  x  Visits Per Year  x  Average Years as a Client", bold: true, size: 24, font: "Courier New", color: BRAND_DARK })],
                    spacing: { after: 0 }
                  })
                ]
              })
            ]
          })
        ]
      }),

      spacer(160),

      new Paragraph({
        children: [new TextRun({ text: "How to find each input:", bold: true, size: 22, color: BRAND_DARK, font: "Arial" })],
        spacing: { after: 100 }
      }),

      // LTV inputs table
      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [2880, 3240, 3240],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders,
                shading: { fill: BRAND_DARK, type: ShadingType.CLEAR },
                margins: { top: 100, bottom: 100, left: 160, right: 160 },
                width: { size: 2880, type: WidthType.DXA },
                children: [new Paragraph({ children: [new TextRun({ text: "INPUT", bold: true, size: 18, color: WHITE, font: "Arial" })] })]
              }),
              new TableCell({
                borders,
                shading: { fill: BRAND_DARK, type: ShadingType.CLEAR },
                margins: { top: 100, bottom: 100, left: 160, right: 160 },
                width: { size: 3240, type: WidthType.DXA },
                children: [new Paragraph({ children: [new TextRun({ text: "WHERE TO FIND IT", bold: true, size: 18, color: WHITE, font: "Arial" })] })]
              }),
              new TableCell({
                borders,
                shading: { fill: BRAND_DARK, type: ShadingType.CLEAR },
                margins: { top: 100, bottom: 100, left: 160, right: 160 },
                width: { size: 3240, type: WidthType.DXA },
                children: [new Paragraph({ children: [new TextRun({ text: "YOUR NUMBER", bold: true, size: 18, color: WHITE, font: "Arial" })] })]
              }),
            ]
          }),
          ...[
            ["Average Visit Value", "Total revenue last 90 days divided by total appointments in the same period", "$________"],
            ["Visits Per Year", "Total appointments last 12 months divided by number of unique clients", "________"],
            ["Avg. Years as a Client", "Review your client list. How long has your average client been coming to you? Start with 2 years if you are unsure.", "________"],
          ].map((row, i) => new TableRow({
            children: row.map((cell, j) => new TableCell({
              borders,
              shading: { fill: i % 2 === 0 ? WHITE : LIGHT_GRAY, type: ShadingType.CLEAR },
              margins: { top: 100, bottom: 100, left: 160, right: 160 },
              width: { size: [2880, 3240, 3240][j], type: WidthType.DXA },
              children: [new Paragraph({ children: [new TextRun({ text: cell, size: 18, color: TEXT_BODY, font: "Arial" })] })]
            }))
          }))
        ]
      }),

      spacer(160),

      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [4680, 4680],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders: noBorders,
                shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
                margins: { top: 140, bottom: 140, left: 220, right: 220 },
                width: { size: 4680, type: WidthType.DXA },
                children: [
                  new Paragraph({
                    children: [new TextRun({ text: "EXAMPLE", bold: true, size: 18, color: BRAND_DARK, font: "Arial" })],
                    spacing: { after: 60 }
                  }),
                  new Paragraph({ children: [new TextRun({ text: "Average Visit Value: $280", size: 18, color: TEXT_BODY, font: "Arial" })], spacing: { after: 40 } }),
                  new Paragraph({ children: [new TextRun({ text: "Visits Per Year: 4", size: 18, color: TEXT_BODY, font: "Arial" })], spacing: { after: 40 } }),
                  new Paragraph({ children: [new TextRun({ text: "Avg. Years as Client: 3", size: 18, color: TEXT_BODY, font: "Arial" })], spacing: { after: 40 } }),
                  new Paragraph({ children: [new TextRun({ text: "LTV = $280 x 4 x 3 = $3,360", bold: true, size: 20, color: BRAND_DARK, font: "Courier New" })] }),
                ]
              }),
              new TableCell({
                borders: noBorders,
                shading: { fill: LIGHT_GRAY, type: ShadingType.CLEAR },
                margins: { top: 140, bottom: 140, left: 220, right: 220 },
                width: { size: 4680, type: WidthType.DXA },
                children: [
                  new Paragraph({
                    children: [new TextRun({ text: "YOUR LTV", bold: true, size: 18, color: BRAND_DARK, font: "Arial" })],
                    spacing: { after: 60 }
                  }),
                  new Paragraph({ children: [new TextRun({ text: "Average Visit Value: $________", size: 18, color: TEXT_BODY, font: "Arial" })], spacing: { after: 40 } }),
                  new Paragraph({ children: [new TextRun({ text: "Visits Per Year: ________", size: 18, color: TEXT_BODY, font: "Arial" })], spacing: { after: 40 } }),
                  new Paragraph({ children: [new TextRun({ text: "Avg. Years as Client: ________", size: 18, color: TEXT_BODY, font: "Arial" })], spacing: { after: 40 } }),
                  new Paragraph({ children: [new TextRun({ text: "My LTV = $________", bold: true, size: 20, color: BRAND_DARK, font: "Courier New" })] }),
                ]
              }),
            ]
          })
        ]
      }),

      spacer(80),

      new Paragraph({
        children: [
          new TextRun({ text: "What your LTV tells you:  ", bold: true, size: 20, color: BRAND_DARK, font: "Arial" }),
          new TextRun({ text: "If your LTV is $3,360, spending $150 to acquire one new client is not an expense. It is a $3,210 return. Knowing this number gives you permission to invest in growth with confidence instead of hesitation.", size: 20, color: TEXT_BODY, font: "Arial" })
        ],
        spacing: { after: 0 }
      }),

      spacer(200),
      rule(),
      spacer(200),

      // KPI 1
      kpiBlock(
        "01", "Customer Acquisition Cost (CAC)",
        "CAC  =  Total Marketing Spend  /  New Clients Acquired",
        "What it costs you to bring one new client through the door. Include ad spend, influencer costs, referral incentives, and any staff time tied to outreach. Track this by channel so you know which marketing actually works.",
        ["Marketing spend this month:", "$________", "", "New clients this month:", "________", "", "My CAC: $________"],
        "$75 to $250 is healthy for most med spas."
      ),

      spacer(200),

      // KPI 2
      kpiBlock(
        "02", "Average Order Value (AOV)",
        "AOV  =  Total Revenue  /  Number of Transactions",
        "How much the average client spends per visit. This number goes up when your team recommends add-ons, when you offer packages, and when retail is presented at checkout. One extra $80 product sale per visit adds up fast at scale.",
        ["Revenue last 30 days:", "$________", "", "Total appointments:", "________", "", "My AOV: $________"],
        "Know your baseline, then set a goal to increase it by 15% within 90 days."
      ),

      spacer(200),

      // KPI 3 - LTV summary reference
      kpiBlock(
        "03", "Client Lifetime Value (LTV)",
        "LTV  =  Avg Visit Value  x  Visits/Year  x  Years as Client",
        "You calculated this above. Come back to it every quarter. Even a small improvement in retention, like keeping clients 1 extra year, can increase LTV by 30 to 50% with zero additional marketing spend.",
        ["My LTV (from above):", "$________", "", "Goal LTV in 12 months:", "$________"],
        "Most med spas operating well see LTV between $1,500 and $6,000+."
      ),

      spacer(200),

      // KPI 4
      kpiBlock(
        "04", "LTV to CAC Ratio",
        "LTV:CAC Ratio  =  LTV  /  CAC",
        "Your growth health score. Divide your LTV by your CAC. Below 2x means you are overspending or underretaining. 3x to 5x is healthy. Above 6x means you are likely underinvesting in marketing and leaving revenue behind.",
        ["My LTV: $________", "", "My CAC: $________", "", "My Ratio: ________x"],
        "3x to 5x = healthy. Above 6x = increase your ad spend."
      ),

      spacer(200),

      // PAGE BREAK
      new Paragraph({ children: [new PageBreak()] }),

      // KPI 5
      kpiBlock(
        "05", "Gross Margin Per Treatment",
        "Gross Margin  =  (Revenue - Direct Costs)  /  Revenue",
        "How much of each treatment dollar stays after paying for injectables, consumables, and provider labor. Not all services are equal. Run this calculation for every service you offer at least once a year. High-volume, low-margin services can quietly drain profit.",
        ["Service: _______________", "Revenue: $________", "Direct costs: $________", "My Margin: ________%"],
        "Strong services run 60% to 80%+ margin. Below 40% needs a hard look."
      ),

      spacer(200),

      // KPI 6
      kpiBlock(
        "06", "Contribution Margin",
        "Contribution Margin  =  Revenue - Variable Costs - CAC",
        "Gross margin tells you if a service is profitable. Contribution margin tells you if the client who came in for that service was worth acquiring. Use this before running any discount promotion or Groupon-style offer.",
        ["Service revenue: $________", "Variable costs: $________", "CAC: $________", "Contribution Margin: $________"],
        "If this number is near zero, the campaign is creating activity but not profit."
      ),

      spacer(200),

      // KPI 7
      kpiBlock(
        "07", "Break-Even Treatments Per Month",
        "Break-Even  =  Fixed Monthly Costs  /  Contribution Margin Per Treatment",
        "How many treatments you need to perform every month before you earn a single dollar of profit. This number should be posted somewhere visible. If you are below it, everything else is noise until you fix it.",
        ["Fixed costs/month: $________", "", "Avg contribution margin:", "$________", "", "Break-even target: ________"],
        "Recalculate any time you add a new provider, equipment, or space."
      ),

      spacer(200),

      // KPI 8
      kpiBlock(
        "08", "Revenue Per Patient (RPP)",
        "RPP  =  Total Revenue  /  Total Unique Clients",
        "Measures the depth of client relationships, not just headcount. A low RPP means your clients are transactional. A high RPP means they trust you, return often, and invest in multiple services. This number improves when providers present comprehensive care options.",
        ["Revenue last 12 months:", "$________", "", "Unique clients:", "________", "", "My RPP: $________"],
        "Track this quarterly. Rising RPP = growing client trust and spend."
      ),

      spacer(200),

      // KPI 9
      kpiBlock(
        "09", "Provider Utilization Rate",
        "Utilization  =  Booked Treatment Hours  /  Available Treatment Hours",
        "How efficiently your providers convert their time into revenue. Gaps, no-shows, and admin during prime hours all drag this down silently. Going from 65% to 80% utilization on the same provider can add tens of thousands of dollars annually with no new overhead.",
        ["Booked hours this week:", "________", "", "Available hours this week:", "________", "", "My Rate: ________%"],
        "Target 75% to 85%. Below 70% is a profit leak. Require deposits."
      ),

      spacer(200),

      // KPI 10
      kpiBlock(
        "10", "Marketing Payback Period",
        "Payback Period  =  CAC  /  Monthly Gross Profit Per Client",
        "How many months to recover what you spent to acquire a client. A membership client paying monthly shortens this dramatically. If any channel has a payback period over 12 months, that channel deserves a serious review.",
        ["My CAC: $________", "", "Monthly gross profit/client:", "$________", "", "Payback Period: ______ months"],
        "Under 6 months is strong. Membership programs are the fastest way to shorten this."
      ),

      spacer(240),
      rule(),
      spacer(200),

      // Summary
      new Paragraph({
        children: [new TextRun({ text: "How These Numbers Connect", bold: true, size: 30, color: BRAND_DARK, font: "Arial" })],
        spacing: { after: 140 }
      }),

      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [9360],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders: {
                  top: { style: BorderStyle.SINGLE, size: 4, color: BRAND_ACCENT },
                  bottom: { style: BorderStyle.SINGLE, size: 4, color: BRAND_ACCENT },
                  left: { style: BorderStyle.SINGLE, size: 4, color: BRAND_ACCENT },
                  right: { style: BorderStyle.SINGLE, size: 4, color: BRAND_ACCENT },
                },
                shading: { fill: BRAND_DARK, type: ShadingType.CLEAR },
                margins: { top: 200, bottom: 200, left: 300, right: 300 },
                width: { size: 9360, type: WidthType.DXA },
                children: [
                  new Paragraph({
                    alignment: AlignmentType.CENTER,
                    children: [new TextRun({ text: "Marketing Spend  >  CAC  >  LTV  >  Margin  >  Cash Flow", bold: true, size: 22, color: BRAND_ACCENT, font: "Courier New" })]
                  })
                ]
              })
            ]
          })
        ]
      }),

      spacer(160),

      ...[
        "Marketing spend drives your CAC. CAC relative to LTV determines whether growth is sustainable.",
        "Gross margin per treatment determines how much of each dollar of LTV actually survives to profit.",
        "Utilization rate determines how efficiently your capacity converts into revenue.",
        "Break-even analysis grounds all of it in your real fixed cost structure.",
        "Owners who track these monthly stop making decisions based on how busy the schedule feels. They make decisions based on what the data says."
      ].map(text => new Paragraph({
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun({ text, size: 20, color: TEXT_BODY, font: "Arial" })],
        spacing: { after: 80 }
      })),

      spacer(200),
      rule(),
      spacer(140),

